import { code } from '../../code.ts';
import { displayName, iosClass, pascal } from '../names.ts';
import type { Plugin } from '../values.ts';

// The path of the file in plugins/ios.
export const path = ({ id }: Plugin) => `${id}/include/${pascal(id)}/${pascal(id)}.h`;

export default ({ id }: Plugin) => {
  const className = iosClass(id);
  return code`
// clang-format off
// Generated by plugins/tools/generate.ts from plugins/plugins/${id}/plugin.json; do not edit.
#import <Foundation/Foundation.h>

NS_ASSUME_NONNULL_BEGIN

/** Error domain of errors returned by \`+[${className} registerPluginWithError:]\`. */
FOUNDATION_EXPORT NSErrorDomain const ${className}ErrorDomain;

/**
 Registers the ${displayName(id)} plugin with MapLibre.

 Call it before creating a map that loads a style using the plugin's layer types.
 Registering again succeeds.
 */
NS_SWIFT_NAME(${pascal(id)}Plugin)
@interface ${className} : NSObject

/**
 Registers the plugin's layer types.

 @param error Set to the reason when registration fails.
 @return \`YES\` when the plugin is registered.
 */
+ (BOOL)registerPluginWithError:(NSError *_Nullable *_Nullable)error NS_SWIFT_NAME(registerPlugin());

- (instancetype)init NS_UNAVAILABLE;

@end

NS_ASSUME_NONNULL_END
`;
};
